def transform(grid):
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h or not w or any(len(row) != w for row in grid):
        raise ValueError("grid must be nonempty and rectangular")

    # Full-width uniform colored rows are periodic row-color clues.
    row_clues = []
    row_mode = True
    for r, row in enumerate(grid):
        nonzero = [value for value in row if value != 0]
        if nonzero:
            if len(nonzero) != w or len(set(nonzero)) != 1:
                row_mode = False
                break
            row_clues.append((r, nonzero[0]))

    if row_mode and row_clues:
        period, colors = _smallest_period(row_clues, h)
        return [[colors[r % period] for _ in range(w)] for r in range(h)]

    # Otherwise the sparse clues lie on down-left/up-right diagonals (r+c constant).
    diagonal_clues = []
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color != 0:
                diagonal_clues.append((r + c, color))
    if not diagonal_clues:
        return [row[:] for row in grid]
    period, colors = _smallest_period(diagonal_clues, min(h, w))
    return [[colors[(r + c) % period] for c in range(w)] for r in range(h)]


